-- E-ONLY UNQUALIFIED READ-ONLY TEMPLATE. Bind ONLY an actual retained completion
-- envelope, never PZ002/abort output. Require independent bank/envelope reader too.
-- One statement returns all durable comparisons and committed-xid/MVCC evidence.
BEGIN READ ONLY;
SET LOCAL statement_timeout='10s';
SET LOCAL timezone='UTC';
WITH completion AS MATERIALIZED (SELECT $completion$__VERIFIED_COMPLETION_ENVELOPE_JSON__$completion$::jsonb c),
baseline AS MATERIALIZED (SELECT c->'before' b FROM completion),
ref AS MATERIALIZED (SELECT (c->>'transaction_id')::numeric t FROM completion),
 mvcc_snapshot AS MATERIALIZED(SELECT pg_current_snapshot() s,pg_current_xact_id_if_assigned()::text observer),
 bank_rows AS MATERIALIZED(SELECT w.xmin::text::numeric low,
 (SELECT jsonb_object_agg(k,v ORDER BY k) FROM jsonb_each(to_jsonb(w)) q(k,v)
 WHERE k IN ('id','user_id','club_id','union_id') OR
 k ~ '(balance|treasury|wallet|chip_pool|locked_chips|held_chips|credit_|diamonds|total_deposited|total_drawn|seeded_amount|surplus_returned|seed_returned_amount)') projection
 FROM public.union_wallets w WHERE union_id='fade0000-0000-0000-0000-000000000001'::uuid),
 versions AS MATERIALIZED(SELECT bank_rows.*,ref.t,
 floor(ref.t/4294967296)*4294967296+low full_xid,
 pg_snapshot_xmax(mvcc_snapshot.s)::text::numeric xmax FROM bank_rows CROSS JOIN ref CROSS JOIN mvcc_snapshot),
 bank_witness AS MATERIALIZED(SELECT jsonb_build_object(
 'reference_transaction_id',ref.t::text,'reference_status',pg_xact_status(ref.t::text::xid8),
 'observer_transaction_id',mvcc_snapshot.observer,'snapshot',mvcc_snapshot.s::text,
 'bank_observation',jsonb_build_object('transaction_id',ref.t::text,
 'snapshot_xmax',pg_snapshot_xmax(mvcc_snapshot.s)::text,'isolation',current_setting('transaction_isolation'),
 'rows',coalesce((SELECT jsonb_agg(jsonb_build_object('projection',v.projection,'xmin',v.low::text,
 'full_xid',v.full_xid::text,
 'eligible',floor(v.t/4294967296)=floor(v.xmax/4294967296) AND v.low>=3 AND v.low>=mod(v.t,4294967296) AND v.full_xid<v.xmax,
 'status',CASE WHEN floor(v.t/4294967296)=floor(v.xmax/4294967296) AND v.low>=3 AND v.low>=mod(v.t,4294967296) AND v.full_xid<v.xmax
 THEN pg_xact_status(v.full_xid::text::xid8) END) ORDER BY v.projection->>'id') FROM versions v),'[]'::jsonb))) witness
 FROM ref CROSS JOIN mvcc_snapshot),
snapshot AS MATERIALIZED (
SELECT jsonb_build_object('observed_at',clock_timestamp(),'transaction_id',(SELECT observer FROM mvcc_snapshot),
 'scoped_rows',jsonb_build_object(
'public.accounting_tournament_fee_owner_bases',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.accounting_tournament_fee_owner_bases WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.accounting_tournament_fee_owner_operations',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.accounting_tournament_fee_owner_operations o WHERE operation_id='341f02a3-4655-420c-b43b-3930b6d9ad8f'::uuid OR events::text LIKE '%2aa4cba1-506f-426b-a1ba-d8e22e018533%' OR EXISTS(SELECT 1 FROM public.accounting_tournament_fee_owner_bases b WHERE b.operation_id=o.operation_id AND b.tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid)) r) scoped),
'public.tournament_players',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.tournament_players WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.tournament_escrow',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.tournament_escrow WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.tournament_terminal_settlements',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.tournament_terminal_settlements WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.engine_tournament_leases',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.engine_tournament_leases WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.accounting_tournament_fee_custody_obligations',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.accounting_tournament_fee_custody_obligations WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.accounting_tournament_fee_recognitions',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.accounting_tournament_fee_recognitions WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.accounting_tournament_recognized_sources',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.accounting_tournament_recognized_sources WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.tournament_rake_settlements',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.tournament_rake_settlements WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.tournament_payouts',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.tournament_payouts WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.spin_reserve_ledger',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.spin_reserve_ledger WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.chip_ledger',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.chip_ledger WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'smarter_private.spin_archived_first_admission',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM smarter_private.spin_archived_first_admission WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped),
'public.tables',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.tables WHERE id='6eaddeaf-1511-4265-bb38-37811ae82ad9'::uuid) r) scoped),
'public.table_seats',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.table_seats WHERE table_id='6eaddeaf-1511-4265-bb38-37811ae82ad9'::uuid) r) scoped),
'public.club_members',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT (SELECT jsonb_object_agg(k,v ORDER BY k) FROM jsonb_each(to_jsonb(r)) e(k,v) WHERE k IN ('id','user_id','club_id','union_id') OR k ~ '(balance|treasury|wallet|chip_pool|locked_chips|held_chips|credit_|diamonds|total_deposited|total_drawn|seeded_amount|surplus_returned|seed_returned_amount)') AS row FROM (SELECT * FROM public.club_members WHERE (club_id='a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid AND user_id IN ('aef849b8-2906-4dc0-b108-251710e76d3c'::uuid,'036f0b55-c601-4d09-982a-5294cf4ea15d'::uuid,'72f2fedb-a5f9-4d10-b147-d92e18102d3f'::uuid)) OR (club_id='a0000000-0000-0000-0000-000000000001'::uuid AND user_id='aef849b8-2906-4dc0-b108-251710e76d3c'::uuid)) r) scoped),
'public.clubs',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT (SELECT jsonb_object_agg(k,v ORDER BY k) FROM jsonb_each(to_jsonb(r)) e(k,v) WHERE k IN ('id','user_id','club_id','union_id') OR k ~ '(balance|treasury|wallet|chip_pool|locked_chips|held_chips|credit_|diamonds|total_deposited|total_drawn|seeded_amount|surplus_returned|seed_returned_amount)') AS row FROM (SELECT * FROM public.clubs WHERE id IN ('a41434bb-8d0c-400a-8f0d-e8b3d65afed4'::uuid,'fade0000-0000-0000-0000-000000000001'::uuid,'a0000000-0000-0000-0000-000000000001'::uuid)) r) scoped),
'public.unions',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT (SELECT jsonb_object_agg(k,v ORDER BY k) FROM jsonb_each(to_jsonb(r)) e(k,v) WHERE k IN ('id','user_id','club_id','union_id') OR k ~ '(balance|treasury|wallet|chip_pool|locked_chips|held_chips|credit_|diamonds|total_deposited|total_drawn|seeded_amount|surplus_returned|seed_returned_amount)') AS row FROM (SELECT * FROM public.unions WHERE id='fade0000-0000-0000-0000-000000000001'::uuid) r) scoped),
'public.union_wallets',(SELECT coalesce(jsonb_agg(projection ORDER BY projection::text),'[]'::jsonb) FROM bank_rows),
'public.spin_bonus_pools',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT (SELECT jsonb_object_agg(k,v ORDER BY k) FROM jsonb_each(to_jsonb(r)) e(k,v) WHERE k IN ('id','user_id','club_id','union_id') OR k ~ '(balance|treasury|wallet|chip_pool|locked_chips|held_chips|credit_|diamonds|total_deposited|total_drawn|seeded_amount|surplus_returned|seed_returned_amount)') AS row FROM (SELECT * FROM public.spin_bonus_pools WHERE id='2d968239-acdd-4a2c-99f2-a369ff37ae31'::uuid) r) scoped),
'public.wallet_credit_idempotency',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.wallet_credit_idempotency WHERE key>='tourney:2aa4cba1-506f-426b-a1ba-d8e22e018533:' AND key<'tourney:2aa4cba1-506f-426b-a1ba-d8e22e018533;') r) scoped),
'public.tournaments',(SELECT coalesce(jsonb_agg(row ORDER BY row::text),'[]'::jsonb) FROM (SELECT to_jsonb(r) AS row FROM (SELECT * FROM public.tournaments WHERE id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid) r) scoped))) evidence
), state AS MATERIALIZED (SELECT b,evidence->'scoped_rows' a FROM baseline CROSS JOIN snapshot),
receipt AS MATERIALIZED (SELECT public.fn_ca_tournament_terminal_receipt('2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid,'aef849b8-2906-4dc0-b108-251710e76d3c'::uuid) r),
parts AS (SELECT b,a,r,r#>'{rake,accounting}' accounting,a->'public.tournament_terminal_settlements'->0 terminal,a->'smarter_private.spin_archived_first_admission'->0 admission,a->'public.tournament_escrow'->0 escrow,a->'public.accounting_tournament_fee_custody_obligations'->0 custody,a->'public.engine_tournament_leases'->0 lease FROM state CROSS JOIN receipt),
expected_accounts AS (SELECT jsonb_agg(x ORDER BY x::text) rows FROM state CROSS JOIN LATERAL jsonb_array_elements(b->'public.club_members') v CROSS JOIN LATERAL (SELECT CASE WHEN v->>'user_id'='aef849b8-2906-4dc0-b108-251710e76d3c' AND v->>'club_id'='a41434bb-8d0c-400a-8f0d-e8b3d65afed4' THEN jsonb_set(v,'{chip_balance}',to_jsonb((v->>'chip_balance')::numeric+200)) ELSE v END x) p),
added_journal AS (SELECT coalesce(jsonb_agg(v),'[]'::jsonb) rows FROM state CROSS JOIN LATERAL jsonb_array_elements(a->'public.chip_ledger') v WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'public.chip_ledger') old WHERE old->>'id'=v->>'id')),
verdict AS MATERIALIZED (
SELECT jsonb_build_object('observed_at',clock_timestamp(),'operation_id','341f02a3-4655-420c-b43b-3930b6d9ad8f',
'baseline_md5',md5(b::text),'committed_scoped_rows',a,'canonical_receipt',r,
'checks',jsonb_build_object(
'genuine_completion_identity',(SELECT c->>'kind'='first_archived_completion_before_commit_v1' AND c->>'operation'='341f02a3-4655-420c-b43b-3930b6d9ad8f' AND c->>'event'='2aa4cba1-506f-426b-a1ba-d8e22e018533' AND c->>'source_sha256'='8a0eb326f88354ac1578729c5286615cfb1b7311c30e410c26e7f6ffb08aa3f5' AND c->'transaction_will_commit'='true'::jsonb AND c->'commit_observed'='false'::jsonb FROM completion),
'actual_completion_committed',(SELECT witness->>'reference_status'='committed' FROM bank_witness),
'durable_nonbank_matches_verified_inside',NOT EXISTS(SELECT 1 FROM completion CROSS JOIN LATERAL jsonb_each(c->'replay_state') x WHERE x.key<>'public.union_wallets' AND a->x.key IS DISTINCT FROM x.value),
'baseline_structure_exact',jsonb_typeof(b)='object' AND (SELECT count(*) FROM jsonb_object_keys(b))=21 AND (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(b) k)=(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(a) k) AND NOT EXISTS(SELECT 1 FROM jsonb_each(b) kv WHERE jsonb_typeof(kv.value) IS DISTINCT FROM 'array'),
'original_four_wallet_identities',(SELECT jsonb_agg(jsonb_build_array(v->>'club_id',v->>'user_id') ORDER BY v->>'club_id',v->>'user_id') FROM jsonb_array_elements(b->'public.club_members') v)=$wallets$[["a0000000-0000-0000-0000-000000000001", "aef849b8-2906-4dc0-b108-251710e76d3c"], ["a41434bb-8d0c-400a-8f0d-e8b3d65afed4", "036f0b55-c601-4d09-982a-5294cf4ea15d"], ["a41434bb-8d0c-400a-8f0d-e8b3d65afed4", "72f2fedb-a5f9-4d10-b147-d92e18102d3f"], ["a41434bb-8d0c-400a-8f0d-e8b3d65afed4", "aef849b8-2906-4dc0-b108-251710e76d3c"]]$wallets$::jsonb,
'qualified_response_identity',(r) @> $expected_qualified_response_identity${"tournament_id": "2aa4cba1-506f-426b-a1ba-d8e22e018533", "winner_id": "aef849b8-2906-4dc0-b108-251710e76d3c", "status": "COMPLETED", "winner_amount": 200, "cash_payout_total": 200, "bounty_payout_total": 0, "receipt_version": 3, "fully_settled": false, "accounting_complete": false, "accounting_state": "fee_custody_unresolved"}$expected_qualified_response_identity$::jsonb,
'qualified_stored_terminal',(terminal) @> $expected_qualified_stored_terminal${"tournament_id": "2aa4cba1-506f-426b-a1ba-d8e22e018533", "winner_id": "aef849b8-2906-4dc0-b108-251710e76d3c", "receipt_version": 3, "accounting_state": "fee_custody_unresolved", "cash_payout_count": 1, "cash_payout_total": 200, "rake_amount": 24, "rake_destination": "tournament_escrow", "escrow_closed_at": null}$expected_qualified_stored_terminal$::jsonb,
'qualified_rake_unattributed',(r->'rake') @> $expected_qualified_rake_unattributed${"amount": 24, "destination": "tournament_escrow", "attributed": false, "attributed_users": 0, "settled_at": null, "attributed_at": null}$expected_qualified_rake_unattributed$::jsonb,
'qualified_exact_accounting',(accounting) @> $expected_qualified_exact_accounting${"accounting_version": 3, "tournament_id": "2aa4cba1-506f-426b-a1ba-d8e22e018533", "status": "fee_custody_unresolved", "player_result": "final", "payable": false, "accounting_complete": false, "resolution": null, "current_held_amount": 24, "held_amount": 24, "source_fingerprint": "bfb56dac635bc7a238383d785ea88f35", "source_count": 1, "reason": "tournament_fee_sources_require_reconciliation", "custody_store": "tournament_escrow", "recognized_source_count": 0, "bank_amount": 0, "banked_at": null, "bank_receipt_id": null}$expected_qualified_exact_accounting$::jsonb,
'custody_obligation_reason',custody->>'tournament_id'='2aa4cba1-506f-426b-a1ba-d8e22e018533' AND custody->>'reason'='tournament_fee_sources_require_reconciliation',
'accounts_exact_four',jsonb_array_length(b->'public.club_members')=4 AND jsonb_array_length(a->'public.club_members')=4,
'winner_200_only',a->'public.club_members' IS NOT DISTINCT FROM (SELECT rows FROM expected_accounts),
'nonbank_reserve_unchanged',NOT EXISTS(SELECT 1 FROM unnest(ARRAY['public.clubs','public.unions','public.spin_bonus_pools','public.spin_reserve_ledger']) k WHERE a->k IS DISTINCT FROM b->k),
'original_journal_preserved',NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b->'public.chip_ledger') old WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a->'public.chip_ledger') nowrow WHERE nowrow=old)),
'one_prize_credit',(SELECT jsonb_array_length(rows)=1 AND rows->0->>'from_type'='prize_liability' AND rows->0->>'from_entity_id'='2aa4cba1-506f-426b-a1ba-d8e22e018533' AND rows->0->>'category'='tournament_prize' AND rows->0->>'to_type'='player_wallet' AND rows->0->>'to_entity_id'='aef849b8-2906-4dc0-b108-251710e76d3c' AND rows->0->>'club_id'='a41434bb-8d0c-400a-8f0d-e8b3d65afed4' AND (rows->0->>'amount')::numeric=200 FROM added_journal),
'receipt_completed_incomplete_accounting',r->'ok'='true'::jsonb AND r->>'status'='COMPLETED' AND r->'fully_settled'='false'::jsonb,
'fee_24_held',accounting->>'status'='fee_custody_unresolved' AND accounting->'accounting_complete'='false'::jsonb AND accounting->'payable'='false'::jsonb AND (accounting->>'held_amount')::numeric=24 AND (accounting->>'current_held_amount')::numeric=24 AND (accounting->>'bank_amount')::numeric=0 AND accounting->>'source_fingerprint'='bfb56dac635bc7a238383d785ea88f35',
'one_terminal_admission_custody',jsonb_array_length(a->'public.tournament_terminal_settlements')=1 AND jsonb_array_length(a->'smarter_private.spin_archived_first_admission')=1 AND jsonb_array_length(a->'public.accounting_tournament_fee_custody_obligations')=1 AND jsonb_array_length(a->'public.tournament_escrow')=1,
'operation_source_funding',admission->>'tournament_id'='2aa4cba1-506f-426b-a1ba-d8e22e018533' AND admission->>'operation_id'='341f02a3-4655-420c-b43b-3930b6d9ad8f' AND admission->>'lease_generation'='341f02a3-4655-420c-b43b-3930b6d9ad8f' AND admission->>'owner_instance'='service:archived-spin-first:341f02a3-4655-420c-b43b-3930b6d9ad8f' AND admission->>'source_sha256'='8a0eb326f88354ac1578729c5286615cfb1b7311c30e410c26e7f6ffb08aa3f5' AND admission->'original_fee_proof'=smarter_private.spin_archived_first_manifest()->'reviewed_fee_proof',
'durable_lease_identity',jsonb_array_length(a->'public.engine_tournament_leases')=1 AND lease->>'tournament_id'='2aa4cba1-506f-426b-a1ba-d8e22e018533' AND lease->>'lease_generation'='341f02a3-4655-420c-b43b-3930b6d9ad8f' AND lease->>'instance_id'=admission->>'owner_instance' AND lease->>'engine_version'='archived-database-projection-v1' AND (lease->>'protocol_version')::integer=2 AND lease->>'acquired_at' IS NOT NULL AND lease->>'heartbeat_at' IS NOT NULL AND (lease->>'acquired_at')::timestamptz >= (SELECT (c->>'transaction_started_at')::timestamptz FROM completion) AND (lease->>'heartbeat_at')::timestamptz >= (lease->>'acquired_at')::timestamptz AND (lease->>'heartbeat_at')::timestamptz <= (SELECT (c->>'inside_observed_at')::timestamptz FROM completion),
'admission_durable_transaction_identity',admission->>'admitted_at' IS NOT NULL AND admission->>'admitted_xid' IS NOT NULL AND admission->>'admitted_xid'=(SELECT c->>'transaction_id' FROM completion) AND admission->>'admitted_at' IS NOT NULL AND (admission->>'admitted_at')::timestamptz=(SELECT (c->>'transaction_started_at')::timestamptz FROM completion) AND admission->'admitted_at'=terminal->'completed_at',
'escrow_custody',(escrow->>'prize_balance')::numeric=0 AND (escrow->>'bounty_balance')::numeric=0 AND (escrow->>'fee_balance')::numeric=24 AND escrow->'closed_at'='null'::jsonb AND (custody->>'amount')::numeric=24 AND custody->>'id'=accounting->>'obligation_id' AND custody->>'source_fingerprint'=accounting->>'source_fingerprint',
'no_false_fee_payment',a->'public.accounting_tournament_fee_recognitions'='[]'::jsonb AND a->'public.accounting_tournament_recognized_sources'='[]'::jsonb AND a->'public.tournament_rake_settlements'='[]'::jsonb,
'original_places',jsonb_array_length(a->'public.tournament_players')=3 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a->'public.tournament_players') nowrow LEFT JOIN LATERAL (SELECT old FROM jsonb_array_elements(b->'public.tournament_players') old WHERE old->>'id'=nowrow->>'id') previous ON true WHERE previous.old IS NULL OR nowrow->>'club_id' IS DISTINCT FROM 'a41434bb-8d0c-400a-8f0d-e8b3d65afed4' OR (nowrow->>'prize')::numeric IS DISTINCT FROM (CASE WHEN nowrow->>'user_id'='aef849b8-2906-4dc0-b108-251710e76d3c' THEN 200 ELSE 0 END) OR (nowrow->>'position')::integer IS DISTINCT FROM (CASE nowrow->>'user_id' WHEN 'aef849b8-2906-4dc0-b108-251710e76d3c' THEN 1 WHEN '036f0b55-c601-4d09-982a-5294cf4ea15d' THEN 2 WHEN '72f2fedb-a5f9-4d10-b147-d92e18102d3f' THEN 3 END) OR nowrow->>'status' IS DISTINCT FROM (CASE WHEN nowrow->>'user_id'='aef849b8-2906-4dc0-b108-251710e76d3c' THEN 'winner' ELSE 'eliminated' END) OR nowrow->'terminal_closed_at' IS DISTINCT FROM terminal->'completed_at' OR (nowrow-ARRAY['status','position','prize','terminal_closed_at']) IS DISTINCT FROM (previous.old-ARRAY['status','position','prize','terminal_closed_at'])),
'no_fabricated_history',NOT EXISTS(SELECT 1 FROM public.hand_history WHERE tournament_id='2aa4cba1-506f-426b-a1ba-d8e22e018533'::uuid OR table_id='6eaddeaf-1511-4265-bb38-37811ae82ad9'::uuid) AND NOT EXISTS(SELECT 1 FROM public.hand_atomic_commits WHERE table_id='6eaddeaf-1511-4265-bb38-37811ae82ad9'::uuid),
'chairs_departed_preserving_stacks',jsonb_array_length(a->'public.table_seats')=3 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a->'public.table_seats') nowrow LEFT JOIN LATERAL (SELECT old FROM jsonb_array_elements(b->'public.table_seats') old WHERE old->>'id'=nowrow->>'id') previous ON true WHERE previous.old IS NULL OR nowrow->>'status' IS DISTINCT FROM 'left' OR nowrow->>'left_at' IS NULL OR nowrow->'stack' IS DISTINCT FROM previous.old->'stack' OR nowrow->'terminal_closed_at' IS DISTINCT FROM terminal->'completed_at' OR nowrow->'active_game_scope' IS DISTINCT FROM 'null'::jsonb OR nowrow->'active_parent_key' IS DISTINCT FROM 'null'::jsonb OR nowrow->'leave_pending' IS DISTINCT FROM 'false'::jsonb OR nowrow->'is_sitting_out' IS DISTINCT FROM 'false'::jsonb OR nowrow->'is_away' IS DISTINCT FROM 'false'::jsonb OR nowrow->'sit_out_at' IS DISTINCT FROM 'null'::jsonb OR nowrow->'scheduled_leave_hands' IS DISTINCT FROM 'null'::jsonb OR (nowrow-ARRAY['left_at','status','leave_pending','is_sitting_out','is_away','sit_out_at','scheduled_leave_hands','updated_at','terminal_closed_at','active_game_scope','active_parent_key']) IS DISTINCT FROM (previous.old-ARRAY['left_at','status','leave_pending','is_sitting_out','is_away','sit_out_at','scheduled_leave_hands','updated_at','terminal_closed_at','active_game_scope','active_parent_key']) OR (previous.old->>'left_at' IS NULL AND nowrow->'left_at' IS DISTINCT FROM terminal->'completed_at') OR (previous.old->>'left_at' IS NOT NULL AND nowrow->'left_at' IS DISTINCT FROM previous.old->'left_at')),
'closed_table',jsonb_array_length(a->'public.tables')=1 AND a->'public.tables'->0->>'status'='closed' AND a->'public.tables'->0->>'lifecycle'='closed' AND (a->'public.tables'->0->>'current_players')::integer=0 AND a->'public.tables'->0->'terminal_closed_at'=terminal->'completed_at',
'exact_seat_receipt',terminal->>'completed_at' IS NOT NULL AND terminal->'settled_at'=terminal->'completed_at' AND (terminal->>'source_seat_count')::integer=3 AND (terminal->>'released_seat_count')::integer=1 AND terminal->'released_seat_ids'='["fd0e0c3a-1efa-4262-8122-4c05e328f9ac"]'::jsonb AND (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_array_elements(terminal->'source_seat_ids') v)=(SELECT jsonb_agg(v->'id' ORDER BY (v->'id')::text) FROM jsonb_array_elements(b->'public.table_seats') v)
),'qualification_limit','Every SQL check must be literal true; mandatory independent completion-envelope and bank-MVCC validation remains separate. Fee24 and oldest alert remain open; no sequence rollback claim.') evidence FROM parts
)
SELECT evidence || jsonb_build_object('all_sql_checks_literal_true',NOT EXISTS(SELECT 1 FROM jsonb_each(evidence->'checks') c WHERE c.value IS DISTINCT FROM 'true'::jsonb)) || jsonb_build_object('completion_envelope',(SELECT c FROM completion),'committed_bank_witness',(SELECT witness FROM bank_witness),'observer_transaction_id',(SELECT observer FROM mvcc_snapshot),'bank_attribution_requires_reader',true) AS evidence FROM verdict;
COMMIT;
